    energygrid[grid.x*grid.y*k + grid.x*j + i+1] += energy1;

    energygrid[grid.x*grid.y*k + grid.x*j + i+2] += energy2;

    energygrid[grid.x*grid.y*k + grid.x*j + i+3] += energy3;

